/**
 * Build the AMD module that draws the migration screens in Moodle 4.0 to 5.2.
 *
 * The screens are the TypeScript of the Moodle 5.3 line. Here Preact stands in for React, Font Awesome 4 names stand in for the
 * ones of Font Awesome 6, and core/ajax stands in for the web service module of Moodle 5.3. The result is amd/src/migration_app.js,
 * which Moodle then minifies into amd/build.
 *
 * Usage: node tools/build-migration.mjs [--check]
 * Without --check it writes amd/src/migration_app.js; with it, it fails when that file is not what the sources produce.
 *
 * @copyright 2026 Didactika.org
 * @author Hector Arrechea <hectorlazaroarrechea@gmail.com>
 * @license https://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

import {build} from 'esbuild';
import {readFileSync, writeFileSync} from 'node:fs';
import {dirname, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';

const plugin = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const output = resolve(plugin, 'amd/src/migration_app.js');
const aliases = new Map([
    ['react', 'preact/compat'],
    ['react-dom', 'preact/compat'],
    ['react-dom/client', 'preact/compat/client'],
    ['react/jsx-runtime', 'preact/jsx-runtime'],
]);
const files = new Map([
    ['@moodle/lms/core/ajax', resolve(plugin, 'js/shims/ajax.ts')],
    ['@moodle/lms/core/amd', resolve(plugin, 'js/shims/amd.ts')],
]);

const substitutions = {
    name: 'substitutions',
    setup(builder) {
        builder.onResolve({filter: /.*/}, async(args) => {
            if (files.has(args.path)) {
                return {path: files.get(args.path)};
            }
            if (args.path.endsWith('/lib/icons') && args.importer.split(String.fromCharCode(92)).join('/').includes('/js/src/')) {
                return {path: resolve(plugin, 'js/overrides/icons.ts')};
            }
            if (aliases.has(args.path)) {
                return builder.resolve(aliases.get(args.path), {resolveDir: plugin, kind: args.kind});
            }
            return undefined;
        });
    },
};

const result = await build({
    entryPoints: [resolve(plugin, 'js/src/entry.tsx')],
    bundle: true,
    format: 'iife',
    globalName: 'FilebankMigration',
    target: 'es2018',
    jsx: 'automatic',
    jsxImportSource: 'preact',
    write: false,
    legalComments: 'none',
    charset: 'ascii',
    logLevel: 'warning',
    plugins: [substitutions],
});

const bundle = result.outputFiles[0].text.replace(/\r\n/g, '\n').replace(/^\/\/# sourceMappingURL=.*$/gm, '').trimEnd();
const header = `// This file is part of Moodle - https://moodle.org/
//
// Moodle is free software: you can redistribute it and/or modify
// it under the terms of the GNU General Public License as published by
// the Free Software Foundation, either version 3 of the License, or
// (at your option) any later version.
//
// Moodle is distributed in the hope that it will be useful,
// but WITHOUT ANY WARRANTY; without even the implied warranty of
// MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the
// GNU General Public License for more details.
//
// You should have received a copy of the GNU General Public License
// along with Moodle.  If not, see <https://www.gnu.org/licenses/>.

/* eslint-disable */

/**
 * The migration screens. This file is generated by tools/build-migration.mjs from js/src, which is a copy of the TypeScript of the
 * Moodle 5.3 line, together with the part of Preact that it uses; do not edit it.
 *
 * @module     local_filebank/migration_app
 * @copyright  2026 Didactika.org
 * @author     Hector Arrechea <hectorlazaroarrechea@gmail.com>
 * @license    https://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

import Ajax from 'core/ajax';
import Toast from 'core/toast';

`;
const footer = `

/**
 * Draw the migrations in the page, with what the element that holds them says in its data-props attribute.
 */
export const init = () => {
    const element = document.getElementById('fbm-root');
    FilebankMigration.mount(
        element,
        JSON.parse(element.dataset.props),
        {ajax: Ajax, modules: {'core/toast': Toast}}
    );
};
`;
const text = header + bundle + footer;

if (process.argv.includes('--check')) {
    const current = readFileSync(output, 'utf8');
    if (current !== text) {
        console.error('amd/src/migration_app.js is not what js/src produces; run node tools/build-migration.mjs');
        process.exit(1);
    }
    console.log('amd/src/migration_app.js is up to date');
} else {
    writeFileSync(output, text);
    console.log('wrote amd/src/migration_app.js (' + text.length + ' bytes)');
}
